      "claim": "B always chats with new people when A and B go to a party",
      "attribute": "social behavior frequency",
      "mechanism": "adverb 'always' modifies the stated behavior",
      "evidence": [
        {"turn_id": 3, "quote": "You are always chatting with new people when we go to a party"}
