    {"turn_id": 1, "status": "no_fact", "reason": "Open question about self-perception; no B fact recoverable"},
    {"turn_id": 3, "status": "facts", "reason": "Retained claims cover shyness, chatting, parties together; added 'always' qualifier"},
    {"turn_id": 5, "status": "no_fact", "reason": "A agrees with B but B's specific statement content is unknown; no new B fact derivable"}
  ]
}
